def components(cells):  # cells: list of (i,j) of a color
    cs=set(cells); out=[]
    for c in cells:
        if c in cs:
            stack=[c]; cs.discard(c); comp=[c]
            while stack:
                a,b=stack.pop()
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if (x,y) in cs: cs.discard((x,y)); stack.append((x,y)); comp.append((x,y))
            out.append(comp)
    return out

