def solve2(g):
    H=len(g);W=len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    size={}
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            v=g[i][j]; stack=[(i,j)]; comp=[]; seen[i][j]=True
            while stack:
                x,y=stack.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==v:
                        seen[a][b]=True; stack.append((a,b))
            for p in comp: size[p]=len(comp)
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=bg and size[(i,j)]==1:
                n=Counter()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=i+dx,j+dy
                    if 0<=x<H and 0<=y<W: n[g[x][y]]+=1
                best=None
                for cc,cnt in n.items():
                    if cc!=bg and cc!=v and cnt>=2: best=cc
                out[i][j]= best if best is not None else bg
    return out
